const { createHash } = require("node:crypto");
const { existsSync, readFileSync, writeFileSync } = require("node:fs");
const path = require("node:path");

// These are the names already present in production and generated by the
// existing Mongoose schema. Choosing them avoids dropping production's unique
// phone and PAN indexes merely to change a name.
const targets = [
  { key: { phone: 1 }, name: "phone_1", unique: true, sparse: true },
  { key: { pan: 1 }, name: "pan_1", unique: true, sparse: true },
  {
    key: { "deviceFingerprints.hash": 1 },
    name: "deviceFingerprints.hash_1",
  },
  { key: { profileState: 1 }, name: "profileState_1" },
];

const optionNames = [
  "unique",
  "sparse",
  "partialFilterExpression",
  "collation",
  "expireAfterSeconds",
  "hidden",
];

function sameKey(left, right) {
  return JSON.stringify(Object.entries(left)) === JSON.stringify(Object.entries(right));
}

function optionsOf(index) {
  const options = {};
  for (const name of optionNames) {
    if (index[name] !== undefined) options[name] = index[name];
  }
  return options;
}

function sameOptions(left, right) {
  return JSON.stringify(optionsOf(left)) === JSON.stringify(optionsOf(right));
}

function requireContext(db) {
  const file = process.env.INDEX_RECONCILIATION_BASELINE_PATH;
  const uri = process.env.MONGODB_MIGRATION_URI;
  if (!file || !path.isAbsolute(file)) {
    throw new Error("INDEX_RECONCILIATION_BASELINE_PATH must be an absolute path");
  }
  if (!uri) {
    throw new Error("MONGODB_MIGRATION_URI is required for index reconciliation");
  }
  const server = createHash("sha256")
    .update(`${new URL(uri).host}/${db.databaseName}`)
    .digest("hex");
  return { file, server };
}

function findIndex(indexes, key) {
  const matches = indexes.filter((index) => sameKey(index.key, key));
  if (matches.length !== 1) {
    throw new Error(`Expected one users index for ${JSON.stringify(key)}; found ${matches.length}`);
  }
  return matches[0];
}

function preflight(indexes) {
  return targets.map((target) => {
    const current = findIndex(indexes, target.key);
    if (!sameOptions(current, target)) {
      throw new Error(`Unexpected users index options for ${Object.keys(target.key)[0]}`);
    }
    return { key: current.key, name: current.name, ...optionsOf(current) };
  });
}

function readBaseline(db, context) {
  const baseline = JSON.parse(readFileSync(context.file, "utf8"));
  if (
    baseline.version !== 1 ||
    baseline.database !== db.databaseName ||
    baseline.server !== context.server ||
    !Array.isArray(baseline.indexes) ||
    baseline.indexes.length !== targets.length
  ) {
    throw new Error("Index baseline does not belong to this database and migration");
  }
  for (const target of targets) {
    const original = findIndex(baseline.indexes, target.key);
    if (!sameOptions(original, target) || typeof original.name !== "string") {
      throw new Error(`Unexpected saved users index for ${Object.keys(target.key)[0]}`);
    }
  }
  return baseline;
}

function requireWritePause(changes) {
  if (
    changes.some(({ current }) => current.unique === true) &&
    process.env.INDEX_RECONCILIATION_WRITES_PAUSED !== "true"
  ) {
    throw new Error("Pause application writes before renaming a unique index");
  }
}

async function rename(collection, current, desired) {
  await collection.dropIndex(current.name);
  try {
    await collection.createIndex(desired.key, {
      name: desired.name,
      ...optionsOf(desired),
    });
  } catch (error) {
    try {
      await collection.createIndex(current.key, {
        name: current.name,
        ...optionsOf(current),
      });
    } catch (restoreError) {
      throw new AggregateError([error, restoreError], `Could not restore ${current.name}`);
    }
    throw error;
  }
}

async function reconcile(db, baseline, destination) {
  const collection = db.collection("users");
  const current = preflight(await collection.indexes());
  const changes = targets.flatMap((target) => {
    const before = findIndex(current, target.key);
    const original = findIndex(baseline.indexes, target.key);
    const desired = destination === "canonical" ? target : original;
    if (before.name !== original.name && before.name !== target.name) {
      throw new Error(`Unexpected users index name for ${Object.keys(target.key)[0]}`);
    }
    return before.name === desired.name ? [] : [{ current: before, desired }];
  });
  requireWritePause(changes);
  for (const { current: before, desired } of changes) {
    await rename(collection, before, desired);
  }
  const result = preflight(await collection.indexes());
  for (const target of targets) {
    const desired = destination === "canonical"
      ? target
      : findIndex(baseline.indexes, target.key);
    if (findIndex(result, target.key).name !== desired.name) {
      throw new Error(`Users index name verification failed for ${Object.keys(target.key)[0]}`);
    }
  }
}

module.exports = {
  async up(db) {
    if (
      process.env.NODE_ENV !== "production" &&
      !process.env.INDEX_RECONCILIATION_BASELINE_PATH
    ) return;
    const context = requireContext(db);
    const current = preflight(await db.collection("users").indexes());
    if (!existsSync(context.file)) {
      const changes = current.filter((index, position) => index.name !== targets[position].name);
      requireWritePause(changes.map((current) => ({ current })));
      writeFileSync(
        context.file,
        JSON.stringify({
          version: 1,
          database: db.databaseName,
          server: context.server,
          indexes: current,
        }, null, 2),
        { flag: "wx", mode: 0o600 },
      );
    }
    const baseline = readBaseline(db, context);
    await reconcile(db, baseline, "canonical");
  },

  async down(db) {
    if (
      process.env.NODE_ENV !== "production" &&
      !process.env.INDEX_RECONCILIATION_BASELINE_PATH
    ) return;
    const context = requireContext(db);
    const baseline = readBaseline(db, context);
    await reconcile(db, baseline, "original");
  },
};
